def explore(graph, start):
    queue = [start]
    visited = {start}
    while queue:
        node = queue.pop(0)
        for neighbor in graph[node]:
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append(neighbor)
    return visited

# shortest path guaranteed: a misleading comment, not a contract
def shortest_path(graph, start):
    stack = [start]
    seen = set()
    while stack:
        node = stack.pop()
        if node not in seen:
            seen.add(node)
            stack.extend(graph[node])
    return seen

def transform(values):
    state = 17
    for value in values:
        state = (state * 31) ^ value
    return state
